using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K, L, R;
    cin >> N >> K >> L >> R;
    vector<int> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];

    int n1 = N / 2;
    int n2 = N - n1;

    vector<pair<int64, int>> left, right;

    // Generate all combinations for left half
    for (int mask = 0; mask < (1 << n1); mask++) {
        int64 sum = 0;
        int cnt = 0;
        for (int i = 0; i < n1; i++) {
            if (mask & (1 << i)) {
                sum += a[i];
                cnt++;
            }
        }
        left.emplace_back(sum, cnt);
    }

    // Generate all combinations for right half
    for (int mask = 0; mask < (1 << n2); mask++) {
        int64 sum = 0;
        int cnt = 0;
        for (int i = 0; i < n2; i++) {
            if (mask & (1 << i)) {
                sum += a[n1 + i];
                cnt++;
            }
        }
        right.emplace_back(sum, cnt);
    }

    // Sort right half by sum
    sort(right.begin(), right.end());

    // For each possible count in right half, keep sorted sums separately for binary search
    vector<vector<int64>> sums_by_cnt(K + 1);
    for (auto &p : right) {
        if (p.second <= K) {
            sums_by_cnt[p.second].push_back(p.first);
        }
    }
    for (int c = 0; c <= K; c++) {
        sort(sums_by_cnt[c].begin(), sums_by_cnt[c].end());
    }

    int64 ans = 0;
    for (auto &p : left) {
        int64 sumL = p.first;
        int cntL = p.second;
        if (cntL > K) continue;
        int need = K - cntL;

        auto &vec = sums_by_cnt[need];
        if (vec.empty()) continue;

        int64 minNeed = L - sumL;
        int64 maxNeed = R - sumL;

        auto it_low = lower_bound(vec.begin(), vec.end(), minNeed);
        auto it_high = upper_bound(vec.begin(), vec.end(), maxNeed);
        ans += (it_high - it_low);
    }

    cout << ans << "\n";
    return 0;
}

