    cin >> N >> K >> L >> R;

    vector<long long> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    long long ans = 0;

    function<void(int,int,long long)> dfs = [&](int idx, int chosen, long long sum) {
        if (chosen == K) {
            if (L <= sum && sum <= R) ++ans;
            return;
        }
        if (idx == N) return;
        if (chosen + (N - idx) < K) return;

        dfs(idx + 1, chosen + 1, sum + a[idx]);
        dfs(idx + 1, chosen, sum);
    };

    dfs(0, 0, 0);

    cout << ans << '\n';
    return 0;
}

