static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static long long count_leq(long long *arr, int n, int k, long long limit) {
    if (k < 0 || k > n) return 0;
    if (k == 0) return 1;              // empty choice
    if (n == 0) return 0;

    int n1 = n / 2;
    int n2 = n - n1;

    long long *left = arr;
    long long *right = arr + n1;

    int maxMask1 = 1 << n1;
    int maxMask2 = 1 << n2;

    long long **sums2 = (long long **)malloc((k + 1) * sizeof(long long *));
    int *cnt2 = (int *)calloc(k + 1, sizeof(int));

    for (int i = 0; i <= k; i++) sums2[i] = NULL;

    // Count how many subset sums of each size in right half
    for (int mask = 0; mask < maxMask2; mask++) {
        int bits = 0;
        long long sum = 0;
        for (int i = 0; i < n2; i++) {
            if (mask & (1 << i)) {
                bits++;
                if (bits > k) break;
                sum += right[i];
            }
        }
        if (bits <= k) cnt2[bits]++;
    }

    for (int i = 0; i <= k; i++) {
        if (cnt2[i] > 0) sums2[i] = (long long *)malloc((size_t)cnt2[i] * sizeof(long long));
        cnt2[i] = 0;
    }

    // Store subset sums of right half grouped by subset size
    for (int mask = 0; mask < maxMask2; mask++) {
        int bits = 0;
        long long sum = 0;
        for (int i = 0; i < n2; i++) {
            if (mask & (1 << i)) {
                bits++;
                if (bits > k) break;
                sum += right[i];
            }
        }
        if (bits <= k) {
            sums2[bits][cnt2[bits]++] = sum;
        }
    }

    for (int i = 0; i <= k; i++) {
        if (cnt2[i] > 1) qsort(sums2[i], cnt2[i], sizeof(long long), cmp_ll);
    }

    long long ans = 0;

    // Enumerate subsets of left half
    for (int mask = 0; mask < maxMask1; mask++) {
        int bits = 0;
        long long sum = 0;
        for (int i = 0; i < n1; i++) {
            if (mask & (1 << i)) {
                bits++;
                if (bits > k) break;
                sum += left[i];
            }
        }
        if (bits > k) continue;

        int need = k - bits;
        if (need < 0 || need > n2) continue;

        long long rem = limit - sum;
        // count sums2[need] <= rem
        int lo = 0, hi = cnt2[need];
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (sums2[need][mid] <= rem) lo = mid + 1;
            else hi = mid;
        }
        ans += lo;
    }

    for (int i = 0; i <= k; i++) free(sums2[i]);
    free(sums2);
    free(cnt2);

    return ans;
}

int main(void) {
    int N, K;
    long long L, R;
    if (scanf("%d %d %lld %lld", &N, &K, &L, &R) != 4) return 0;

    long long *a = (long long *)malloc((size_t)N * sizeof(long long));
    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);

    long long ans = count_leq(a, N, K, R) - count_leq(a, N, K, L - 1);
    printf("%lld\n", ans);

    free(a);
    return 0;
}

