public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        long L = sc.nextLong();
        long R = sc.nextLong();
        long[] a = new long[N];
        for (int i = 0; i < N; i++) {
            a[i] = sc.nextLong();
        }

        int n1 = N / 2;
        int n2 = N - n1;
        long[] first = Arrays.copyOfRange(a, 0, n1);
        long[] second = Arrays.copyOfRange(a, n1, N);

        List<long[]> leftSums = generateSums(first);
        List<long[]> rightSums = generateSums(second);

        // Group right sums by count
        Map<Integer, List<Long>> rightByCount = new HashMap<>();
        for (long[] pair : rightSums) {
            int count = (int) pair[0];
            long sum = pair[1];
            rightByCount.computeIfAbsent(count, k -> new ArrayList<>()).add(sum);
        }
        for (List<Long> list : rightByCount.values()) {
            Collections.sort(list);
        }

        long ans = 0;
        for (long[] pair : leftSums) {
            int c1 = (int) pair[0];
            long s1 = pair[1];
            int need = K - c1;
            if (need < 0) continue;
            List<Long> list = rightByCount.get(need);
            if (list == null) continue;
            long low = L - s1;
            long high = R - s1;
            // binary search for range [low, high]
            int leftIdx = lowerBound(list, low);
            int rightIdx = upperBound(list, high);
            ans += (rightIdx - leftIdx);
        }

        System.out.println(ans);
    }

    static List<long[]> generateSums(long[] arr) {
        List<long[]> res = new ArrayList<>();
        int n = arr.length;
        for (int mask = 0; mask < (1 << n); mask++) {
            long sum = 0;
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += arr[i];
                    count++;
                }
            }
            res.add(new long[]{count, sum});
        }
        return res;
    }

    static int lowerBound(List<Long> list, long key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid) < key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(List<Long> list, long key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid) <= key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

