public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        int L = sc.nextInt();
        int R = sc.nextInt();

        int[] a = new int[N];
        for (int i = 0; i < N; i++) {
            a[i] = sc.nextInt();
        }

        // dp[j][s] = number of ways to choose j coins with sum s
        // after considering first i coins
        int maxSum = 0;
        for (int v : a) maxSum += v;

        long[][] dp = new long[K + 1][maxSum + 1];
        dp[0][0] = 1;

        for (int i = 0; i < N; i++) {
            // Iterate in reverse to avoid using same coin twice
            for (int j = Math.min(i + 1, K); j >= 1; j--) {
                for (int s = maxSum; s >= a[i]; s--) {
                    dp[j][s] += dp[j-1][s - a[i]];
                }
            }
        }

        long ans = 0;
        for (int s = L; s <= Math.min(R, maxSum); s++) {
            ans += dp[K][s];
        }

        System.out.println(ans);
    }
}

