public class Main {
    static int N, K;
    static long L, R;
    static long[] a;
    static long answer = 0;

    static class Pair {
        long sum;
        int cnt;
        Pair(long sum, int cnt) {
            this.sum = sum;
            this.cnt = cnt;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        N = fs.nextInt();
        K = fs.nextInt();
        L = fs.nextLong();
        R = fs.nextLong();

        a = new long[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextLong();

        int mid = N / 2;
        long[] left = Arrays.copyOfRange(a, 0, mid);
        long[] right = Arrays.copyOfRange(a, mid, N);

        ArrayList<Pair> leftSubs = generate(left);
        ArrayList<Pair> rightSubs = generate(right);

        ArrayList<Long>[] rightByCount = new ArrayList[K + 1];
        for (int i = 0; i <= K; i++) rightByCount[i] = new ArrayList<>();

        for (Pair p : rightSubs) {
            if (p.cnt <= K) rightByCount[p.cnt].add(p.sum);
        }

        for (int i = 0; i <= K; i++) {
            Collections.sort(rightByCount[i]);
        }

        long ans = 0;
        for (Pair lp : leftSubs) {
            if (lp.cnt > K) continue;
            int need = K - lp.cnt;
            if (need < 0 || need > K) continue;

            ArrayList<Long> list = rightByCount[need];
            long low = L - lp.sum;
            long high = R - lp.sum;

            int leftIdx = lowerBound(list, low);
            int rightIdx = upperBound(list, high);
            ans += (rightIdx - leftIdx);
        }

        System.out.println(ans);
    }

    static ArrayList<Pair> generate(long[] arr) {
        int m = arr.length;
        ArrayList<Pair> res = new ArrayList<>();
        int total = 1 << m;
        for (int mask = 0; mask < total; mask++) {
            long sum = 0;
            int cnt = 0;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum += arr[i];
                    cnt++;
                }
            }
            res.add(new Pair(sum, cnt));
        }
        return res;
    }

    static int lowerBound(ArrayList<Long> list, long target) {
        int l = 0, r = list.size();
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (list.get(mid) >= target) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    static int upperBound(ArrayList<Long> list, long target) {
        int l = 0, r = list.size();
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (list.get(mid) > target) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
